//jaywcjlove.github.io/maslink/?id=6739052447" title="DayBar for macOS"><img alt="DayBar" height="52" src="https://wangchujiang.com/appicon/daybar.png"></a>\n  <a target="_blank" href="https://jaywcjlove.github.io/maslink/?id=6739444407" title="Iconed for macOS"><img alt="Iconed" height="52" src="https://wangchujiang.com/appicon/iconed.png"></a>\n  <a target="_blank" href="https://jaywcjlove.github.io/maslink/?id=6737160756" title="Menuist for macOS"><img alt="Menuist" height="52" src="https://wangchujiang.com/appicon/rightmenu-master.png"></a>\n  <a target="_blank" href="https://jaywcjlove.github.io/maslink/?id=6723903021" title="Paste Quick for macOS"><img alt="Quick RSS" height="52" src="https://wangchujiang.com/appicon/paste-quick.png"></a>\n  <a target="_blank" href="https://jaywcjlove.github.io/maslink/?id=6670696072&platform=mac" title="Quick RSS for macOS/iOS"><img alt="Quick RSS" height="52" src="https://wangchujiang.com/appicon/quick-rss.png"></a>\n  <a target="_blank" href="https://jaywcjlove.github.io/maslink/?id=6670167443" title="Web Serve for macOS"><img alt="Web Serve" height="52" src="https://wangchujiang.com/appicon/web-serve.png"></a>\n  <a target="_blank" href="https://jaywcjlove.github.io/maslink/?id=6503953628&platform=mac" title="Copybook Generator for macOS/iOS"><img alt="Copybook Generator" height="52" src="https://wangchujiang.com/appicon/copybook-generator.png"></a>\n  <a target="_blank" href="https://jaywcjlove.github.io/maslink/?id=6471227008&platform=mac" title="DevTutor for macOS/iOS"><img alt="DevTutor for SwiftUI" height="52" src="https://wangchujiang.com/appicon/devtutor.png"></a>\n  <a target="_blank" href="https://jaywcjlove.github.io/maslink/?id=6479819388&platform=mac" title="RegexMate for macOS/iOS"><img alt="RegexMate" height="52" src="https://wangchujiang.com/appicon/regex-mate.png"></a>\n  <a target="_blank" href="https://jaywcjlove.github.io/maslink/?id=6479194014&platform=mac" title="Time Passage for macOS/iOS"><img alt="Time Passage" height="52" src="https://wangchujiang.com/appicon/time-passage.png"></a>\n  <a target="_blank" href="https://jaywcjlove.github.io/maslink/?id=6478772538" title="IconizeFolder for macOS"><img alt="Iconize Folder" height="52" src="https://wangchujiang.com/appicon/iconize-folder.png"></a>\n  <a target="_blank" href="https://jaywcjlove.github.io/maslink/?id=6478511402&platform=mac" title="Textsound Saver for macOS/iOS"><img alt="Textsound Saver" height="52" src="https://wangchujiang.com/appicon/textsound-saver.png"></a>\n  <a target="_blank" href="https://jaywcjlove.github.io/maslink/?id=6476924627" title="Create Custom Symbols for macOS"><img alt="Create Custom Symbols" height="52" src="https://wangchujiang.com/appicon/create-custom-symbols.png"></a>\n  <a target="_blank" href="https://jaywcjlove.github.io/maslink/?id=6476452351" title="DevHub for macOS"><img alt="DevHub" height="52" src="https://wangchujiang.com/appicon/devhub.png"></a>\n  <a target="_blank" href="https://jaywcjlove.github.io/maslink/?id=6476400184" title="Resume Revise for macOS"><img alt="Resume Revise" height="52" src="https://wangchujiang.com/appicon/resume-revise.png"></a>\n  <a target="_blank" href="https://jaywcjlove.github.io/maslink/?id=6472593276" title="Palette Genius for macOS"><img alt="Palette Genius" height="52" src="https://wangchujiang.com/appicon/palette-genius.png"></a>\n  <a target="_blank" href="https://jaywcjlove.github.io/maslink/?id=6470879005" title="Symbol Scribe for macOS"><img alt="Symbol Scribe" height="52" src="https://wangchujiang.com/appicon/symbol-scribe.png"></a>\n</div>\n<hr>\n\nInput \u8f93\u5165\u6846\n===\n\n[![Buy me a coffee](https://img.shields.io/badge/Buy%20me%20a%20coffee-048754?logo=buymeacoffee)](https://jaywcjlove.github.io/#/sponsor)\n[![Telegram Channel](https://img.shields.io/badge/%20-Telegram-00618f.svg?logo=Telegram)](https://t.me/s/AwesomeMacApps)\n[![Follow On X](https://img.shields.io/badge/Follow%20on%20X-333333?logo=x&logoColor=white)](https://x.com/jaywcjlove)\n[![Open in unpkg](https://img.shields.io/badge/Open%20in-unpkg-blue)](https://uiwjs.github.io/npm-unpkg/#/pkg/@uiw/react-input/file/README.md)\n[![NPM Downloads](https://img.shields.io/npm/dm/@uiw/react-input.svg?style=flat)](https://www.npmjs.com/package/@uiw/react-input)\n[![npm version](https://img.shields.io/npm/v/@uiw/react-input.svg?label=@uiw/react-input)](https://npmjs.com/@uiw/react-input)\n\n\u901a\u8fc7\u9f20\u6807\u6216\u952e\u76d8\u8f93\u5165\u5185\u5bb9\uff0c\u662f\u6700\u57fa\u7840\u7684\u8868\u5355\u57df\u7684\u5305\u88c5\u3002\n\n```jsx\nimport { Input } from \'uiw\';\n// or\nimport Input from \'@uiw/react-input\';\n```\n\n### \u57fa\u7840\u7528\u6cd5\n\n```jsx mdx:preview&bg=#fff\nimport React from \'react\';\nimport { Input } from \'uiw\';\n\nexport default function Demo() {\n  return (\n    <div>\n      <Input placeholder="\u8bf7\u8f93\u5165\u5185\u5bb9" style={{ maxWidth: 200 }} />\n    </div>\n  );\n}\n```\n\n### \u6570\u5b57\u8f93\u5165\u6846\n\n```jsx mdx:preview&bg=#fff\nimport React from \'react\';\nimport { InputNumber, Row, Col } from \'uiw\';\n\nexport default function Demo() {\n  return (\n    <div>\n      <Row gutter={10}>\n        <Col fixed>\n          <InputNumber\n            placeholder="\u8bf7\u8f93\u5165\u5185\u5bb9"\n            style={{ width: 200 }}\n          />\n        </Col>\n        <Col fixed>\u9650\u5236\u5927\u5c0f</Col>\n        <Col fixed>\n          <InputNumber\n            placeholder="\u8bf7\u8f93\u5165\u5185\u5bb9"\n            style={{ width: 200 }}\n            min={1}\n            max={10}\n          />\n        </Col>\n        <Col fixed>\u8d85\u51fa\u9650\u754c\u8b66\u544a</Col>\n        <Col fixed>\n          <InputNumber\n            placeholder="\u8bf7\u8f93\u5165\u5185\u5bb9"\n            style={{ width: 200 }}\n            min={1}\n            max={10}\n            overLimitColor={\'red\'}\n          />\n        </Col>\n        <Col fixed>\u8bbe\u7f6e\u6b65\u6da8\u503c</Col>\n        <Col fixed>\n          <InputNumber\n            placeholder="\u8bf7\u8f93\u5165\u5185\u5bb9"\n            style={{ width: 200 }}\n            step={5}\n          />\n        </Col>\n      </Row>\n    </div>\n  )\n};\n```\n\n### Form \u4e2d\u4f7f\u7528 Input\n\n```jsx mdx:preview&bg=#fff\nimport React from \'react\';\nimport { Form, Input, InputNumber, Row, Col, Button, Notify } from \'uiw\';\n\nexport default function Demo() {\n  return (\n    <Form\n      onChange={({ initial, current }) => { }}\n      onSubmitError={(error) => {\n        console.log(\'error:\', error)\n        return error && error.filed ? { ...error.filed } : null;\n      }}\n      onSubmit={({initial, current}) => {\n        if (current.input && current.input.length > 3) {\n          Notify.success({\n            title: \'\u63d0\u4ea4\u6210\u529f\uff01\',\n            description: `\u586b\u5199\uff1a\u3010${current.input.toString()}\u3011\uff01`\n          });\n        } else {\n          Notify.error({ title: \'\u63d0\u4ea4\u5931\u8d25\uff01\', description: \'\u5fc5\u987b\u957f\u5ea6\u8d85\u8fc7 3 \u4e2a\u5b57\u7b26\uff01\' });\n        }\n        const ErrObj = {};\n        if (current.input && current.input.length < 4) {\n          ErrObj.input = \'\ud83d\ude06 \u5fc5\u987b\u957f\u5ea6\u8d85\u8fc7 3 \u4e2a\u5b57\u7b26\uff01\';\n        }\n        if(Object.keys(ErrObj).length > 0) {\n          const err = new Error();\n          err.filed = ErrObj;\n          throw err;\n        }\n      }}\n      fields={{\n        input: {\n          value: \'www\',\n          label: \'\u8bf7\u8f93\u5165\u5185\u5bb9\',\n          help: \'\u5fc5\u987b\u957f\u5ea6\u8d85\u8fc7 3 \u4e2a\u5b57\u7b26\uff01\',\n          validator: (value = \'\') => value.length < 4 ? \'\u5fc5\u586b\u9009\u9879\uff01\' : null,\n          children: <Input placeholder="\u8bf7\u8f93\u5165\u5185\u5bb9" style={{ maxWidth: 200 }} />,\n        },\n        inputNumber: {\n          value: \'www\',\n          label: \'\u8bf7\u8f93\u5165\u5185\u5bb9\',\n          help: \'\u5fc5\u987b\u957f\u5ea6\u8d85\u8fc7 3 \u4e2a\u5b57\u7b26\uff01\',\n          validator: (value = \'\') => value.length < 4 ? \'\u5fc5\u586b\u9009\u9879\uff01\' : null,\n          children: <InputNumber placeholder="\u8bf7\u8f93\u5165\u5185\u5bb9" style={{ maxWidth: 200 }} />,\n        },\n      }}\n    >\n      {({ fields, state, canSubmit }) => {\n        return (\n          <div>\n            <Row>\n              <Col>{fields.input}</Col>\n            </Row>\n            <Row>\n              <Col>{fields.inputNumber}</Col>\n            </Row>\n            <Row>\n              <Col>\n                <Button disabled={!canSubmit()} type="primary" htmlType="submit">\u63d0\u4ea4</Button>\n              </Col>\n            </Row>\n            <Row>\n              <Col>\n                <pre style={{ padding: 10, marginTop: 10 }}>\n                  {JSON.stringify(state.current, null, 2)}\n                </pre>\n              </Col>\n            </Row>\n          </div>\n        );\n      }}\n    </Form>\n  );\n}\n```\n\n### \u63d2\u5165\u56fe\u6807\n\n```jsx mdx:preview&bg=#fff\nimport React from \'react\';\nimport { Input, Row, Col } from \'uiw\';\n\nconst stylItem = { margin: 20 };\nexport default function Demo() {\n  return (\n    <div>\n      <Row gutter={10}>\n        <Col fixed>\n          <Input preIcon="delete" placeholder="\u8bf7\u8f93\u5165\u5185\u5bb9" />\n        </Col>\n        <Col fixed>\n          <Input preIcon="tag" placeholder="\u8bf7\u8f93\u5165\u5185\u5bb9" />\n        </Col>\n        <Col fixed>\n          <Input preIcon="picasa" placeholder="\u8bf7\u8f93\u5165\u5185\u5bb9" />\n        </Col>\n        <Col fixed>\n          <Input preIcon="like-o" placeholder="\u8bf7\u8f93\u5165\u5185\u5bb9" />\n        </Col>\n      </Row>\n    </div>\n  )\n}\n```\n\n### \u540e\u9762\u63d2\u5165\u5185\u5bb9\n\n\u5411\u540e\u9762\u63d2\u5165 [`Button`](#/components/button) \u6216\u8005 [`Tag`](#/components/tag)\n\n```jsx mdx:preview&bg=#fff\nimport React from \'react\';\nimport { Input, Row, Col, Button, Tag } from \'uiw\';\n\nexport default function Demo() {\n  return (\n    <div>\n      <Row gutter={10}>\n        <Col fixed>\n          <Input\n            preIcon="like-o"\n            placeholder="\u8bf7\u8f93\u5165\u5bc6\u7801"\n            addonAfter={<Button icon="lock" size="small" basic type="light" />}\n          />\n        </Col>\n        <Col fixed>\n          <Input\n            preIcon="tag"\n            placeholder="\u8bf7\u8f93\u5165\u5185\u5bb9"\n            addonAfter={<Tag title="1000" color="#28a745" />}\n          />\n        </Col>\n        <Col fixed>\n          <Input\n            preIcon="search"\n            placeholder="\u8bf7\u8f93\u5165\u5185\u5bb9"\n            addonAfter={<Button icon="apple" size="small" type="primary">\u6309\u94ae</Button>}\n          />\n        </Col>\n        <Col fixed>\n          <Input\n            preIcon="tag"\n            placeholder="\u8bf7\u8f93\u5165\u5185\u5bb9"\n            addonAfter={<Button size="small" type="primary">\u6309\u94ae</Button>}\n          />\n        </Col>\n      </Row>\n    </div>\n  )\n}\n```\n\n### \u8f93\u5165\u6846\u5c3a\u5bf8\n\n```jsx mdx:preview&bg=#fff\nimport React from \'react\';\nimport { Input, Row, Col, Tag, Button } from \'uiw\';\n\nexport default function Demo() {\n  return (\n    <div>\n      <Row gutter={10} style={{ marginBottom: 10 }}>\n        <Col fixed>\n          <Input\n            preIcon="like-o"\n            size="large"\n            placeholder="\u8bf7\u8f93\u5165\u5bc6\u7801"\n            addonAfter={<Button icon="lock" basic type="light" />}\n          />\n        </Col>\n        <Col fixed>\n          <Input\n            preIcon="search"\n            placeholder="\u8bf7\u8f93\u5165\u5185\u5bb9"\n            addonAfter={<Button icon="arrow-right" basic size="small" type="light" />}\n          />\n        </Col>\n        <Col fixed>\n          <Input\n            preIcon="tag"\n            size="small"\n            placeholder="\u8bf7\u8f93\u5165\u5185\u5bb9"\n            addonAfter={<Button size="small" type="primary">\u6309\u94ae</Button>}\n          />\n        </Col>\n      </Row>\n      <Row gutter={10} style={{ marginBottom: 10 }}>\n        <Col fixed>\n          <Input\n            preIcon="like-o"\n            size="large"\n            placeholder="\u8bf7\u8f93\u5165\u5bc6\u7801"\n            addonAfter={<Tag title="1000" color="#28a745" />}\n          />\n        </Col>\n        <Col fixed>\n          <Input\n            preIcon="tag"\n            placeholder="\u8bf7\u8f93\u5165\u5185\u5bb9"\n            addonAfter={<Tag title="\u836f\u4e38" color="#1C7CEB" color="#40bf16">\u4e38</Tag>}\n          />\n        </Col>\n        <Col fixed>\n          <Input\n            preIcon="tag"\n            size="small"\n            placeholder="\u8bf7\u8f93\u5165\u5185\u5bb9"\n            addonAfter={<Tag title="1000" color="#28a745" />}\n          />\n        </Col>\n      </Row>\n      <Row gutter={10} style={{ marginBottom: 10 }}>\n        <Col fixed>\n          <Input\n            preIcon="like-o"\n            size="large"\n            placeholder="\u8bf7\u8f93\u5165\u5bc6\u7801"\n            addonAfter={<Button icon="apple" type="primary">\u6309\u94ae</Button>}\n          />\n        </Col>\n        <Col fixed>\n          <Input\n            preIcon="search"\n            placeholder="\u8bf7\u8f93\u5165\u5185\u5bb9"\n            addonAfter={<Button size="small" type="primary">\u641c\u7d22</Button>}\n          />\n        </Col>\n        <Col fixed>\n          <Input\n            preIcon="tag"\n            size="small"\n            placeholder="\u8bf7\u8f93\u5165\u5185\u5bb9"\n            addonAfter={<Button size="small" type="primary">\u6309\u94ae</Button>}\n          />\n        </Col>\n      </Row>\n      <Row gutter={10} style={{ marginBottom: 10 }}>\n        <Col fixed>\n          <Input\n            preIcon="like-o"\n     